import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Route, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import moment, { Moment } from "moment";
import { UserSessionService } from 'src/app/services/usersession.service';
@Component({
  selector: 'app-awc-add-std',
  templateUrl: './awc-add-std.page.html',
  styleUrls: ['./awc-add-std.page.scss'],
})
export class AwcAddStdPage implements OnInit {

  addStdFrom: FormGroup;
  paramData: any = '';
  submitted: boolean = false;
  routeData: any;
  phase_id: any;
  viewstatus: any;
  phaseName: any;
  AcYears: any;

  constructor(private router: Router, private route: ActivatedRoute, private userService: UserService,
     private alertService: AlertService, private userSessionService:UserSessionService) {

  }

  ngOnInit() {
    this.addStdFrom = new FormGroup({
      Childname: new FormControl('', [Validators.required, Validators.pattern('^[a-zA-Z _ ]+$')]),
      ChildDob: new FormControl('', Validators.required),
      Gender: new FormControl('', Validators.required),
      BirthWeight: new FormControl('', [Validators.required, Validators.pattern('^([1-5]|[1-4].[0-9]||[1-4].[0-9][1-9]|[0].[5-9]|[0].[5-9][0-9])$')]),
      Parentname: new FormControl('', [Validators.required, Validators.pattern('^[a-zA-Z _ ]+$')]),
      Parentmobileno: new FormControl('', [Validators.required, Validators.pattern('^[6-9][0-9]{9,9}$')]),
      AdhaarNo: new FormControl('', Validators.pattern('^[0-9]{12,12}$')),
      ChildRchid: new FormControl('',Validators.pattern('^[0-9]{12,12}$')),
      picmeID: new FormControl('',Validators.pattern('^[0-9]{12,12}$'))
    });
  }

 
  onGoButton() {
    this.router.navigate(['/tabs/awc-student-list'], { queryParams: { data: JSON.stringify(this.paramData) ,id: this.phase_id ,viewstatus: this.viewstatus,phaseName :this.phaseName,AcYears : this.AcYears } });
  }

  ionViewDidEnter() {
    this.submitted = false;
    this.addStdFrom.reset();
    this.paramData = JSON.parse(this.route.snapshot.queryParams.data);
    this.routeData = this.route.snapshot;
    this.phase_id = this.routeData.queryParams.id ;
    this.viewstatus = this.routeData.queryParams.viewstatus;
    this.phaseName = this.routeData.queryParams.phaseName;
    this.AcYears = this.routeData.queryParams.AcYears;
  }

  onSubmit() {
    this.submitted = true;
    // let data: any ={};
    let newDate = moment(new Date()).format('YYYY-MM-DD HH:mm:ss');
    if (this.addStdFrom.valid) {
      let obj:any = {
        records:{
          DistrictId : this.userSessionService.district_id(),
          DistrictName : this.paramData.DistrictName,
          BlockId : this.userSessionService.mht_block_id(),
          HealthBlockName : '',
          AwcCode : this.paramData.AwcCode,
          AwcName : this.paramData.AwcName,
          StatusType : 99,
          Addedts: newDate
        }
      }
      ;
      Object.entries(this.addStdFrom.value).forEach(([key, value]) => {
        obj.records[key] = value;
      });
      obj.records.ChildDob= moment(this.addStdFrom.value.ChildDob).format('YYYY-MM-DD')
      obj.records.IndexId = '';
      this.userService.AwcAnganvadiStuCUD(obj).subscribe((res) => {
        if (res.dataStatus) {
          this.submitted = false;
          // this.studentList = res.result;
          this.router.navigate(['/tabs/awc-student-list'], { queryParams: { data: JSON.stringify(this.paramData),id: this.phase_id ,viewstatus: this.viewstatus,phaseName :this.phaseName,AcYears : this.AcYears } });
        } else {
          this.alertService.warning(res.message);
        }
      });
    } else {
      this.alertService.warning('Form is invalid'); 
    }
  }
}



